using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class FinishHud08DockAuthoring{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var n in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+n+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var d=h.Layout.CompactDock;d.PowerSummary=h.GetComponentsInChildren<RectTransform>(true).Single(r=>r.name=="PowerSummary");EditorUtility.SetDirty(d);if(d.HeaderInput==null){d.HeaderInput=d.Header.GetComponent<CanvasGroup>();if(d.HeaderInput==null)d.HeaderInput=d.Header.gameObject.AddComponent<CanvasGroup>();EditorUtility.SetDirty(d);}var host=h.Groups.Construction.transform.Find("BuildDetailsSlide") as RectTransform;if(host==null){host=new GameObject("BuildDetailsSlide",typeof(RectTransform)).GetComponent<RectTransform>();host.SetParent(h.Groups.Construction.transform,false);host.anchorMin=Vector2.zero;host.anchorMax=Vector2.one;host.offsetMin=host.offsetMax=Vector2.zero;d.CostPanel.SetParent(host,false);d.GoalPanel.SetParent(host,false);h.Groups.ConstructionSlides=h.Groups.ConstructionSlides.Concat(new[]{new HudModeGroups.Slide{Host=host,Direction=Vector2.right}}).ToArray();}d.Apply(1);EditorUtility.SetDirty(h.Groups);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Details follow the saved right-edge group easing";}}
